typedef struct vector3d
{
  float x;
  float y;
  float z;
} vector3d;

typedef struct trail_node_t trail_node_t;

typedef struct
{
  vector3d current __attribute__((aligned(16)));
  vector3d start __attribute__((aligned(16)));
  vector3d *trailpt;
  trail_node_t *trail_node;
  vector3d vel;
  float seed;
  float age;
  float life;
  int valid;
} spray_control_t;

#define MAX_SPRAY_PTS 25

class trail
{
public:
  bool spraypt_add (spray_control_t *SC, spray_control_t *ListPtr, int *ListCount);
  void spraypt_pos (spray_control_t *SC);
};

bool trail::spraypt_add (spray_control_t *SC, spray_control_t *ListPtr, int *ListCount)
{
  if (SC->trailpt == ListPtr[*ListCount].trailpt)
    return false;

	*ListCount = 1 + *ListCount;
	if(*ListCount>=MAX_SPRAY_PTS)
		*ListCount=0;

	spraypt_pos(SC);

	ListPtr[*ListCount].age = 0;
	ListPtr[*ListCount].life = SC->life;
	ListPtr[*ListCount].trailpt = SC->trailpt;
	ListPtr[*ListCount].vel = SC->vel;
	ListPtr[*ListCount].start = SC->start;
	ListPtr[*ListCount].current = SC->current;
	ListPtr[*ListCount].valid = 1;
	ListPtr[*ListCount].trail_node = SC->trail_node;

  return true;
}
